long long mod = MOD;

int main() {
    long long L, R;
    scanf("%lld %lld", &L, &R);

    long long ans = 0;

    // Iterate over highest bit position
    for (int k = 0; (1LL << k) <= R; k++) {
        long long low = 1LL << k;          // smallest with bit k set
        long long high = (1LL << (k+1)) - 1; // largest with bit k set
        if (high < L) continue;
