        }

        for (long long x = start; x <= end; x++) {
            int zero_bits = 0;
            for (int b = 0; b < k; b++) {
                if (!(x & (1LL << b))) zero_bits++;
            }
            ans = (ans + pow2[zero_bits]) % mod;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

