#define MOD 1000000007LL

/*
Condition:
y % x == (y ^ x), with L <= x <= y <= R.

Let y = qx + r, where 0 <= r < x and r = y % x.
We need:
r = y ^ x

Since y ^ x can be >= x in general, but r < x, this strongly restricts cases.

Observe:
If y = x, then y % x = 0 and y ^ x = 0, so every pair (x, x) works.

For y > x:
If q >= 2, then y >= 2x, so y % x = r < x.
But y ^ x differs in higher bits due to the quotient contribution and cannot equal r < x.
More directly, the only possible case is q = 1, i.e. y = x + r with 0 < r < x.

Then:
y ^ x = (x + r) ^ x
For this to equal r, addition of r to x must produce no carries in binary.
That is exactly:
x & r == 0

So all valid pairs are:
1) y = x  (all x)
2) y = x + r, where 1 <= r < x, x + r <= R, and (x & r) == 0

Equivalently, for y > x:
y = x | r, with r a non-empty subset of zero-bits of x below its highest bit,
and y <= R.

A cleaner counting form:
For fixed x, valid y are exactly numbers y in [x, min(R, 2x-1)] such that
y = x + r and (x & r) = 0.
This is equivalent to choosing bits only where x has 0 among positions below msb(x).

If x has k zero bits below its highest set bit, then total possible y in [x, 2x-1] is 2^k
(including y=x). We need only those <= R.

We count using digit-DP on the available zero-bit positions of x:
number of subsets s such that x + s <= R, where s uses only zero-bit positions below msb(x).

For each x in [L, R], answer adds countSubsets(x, R).

This is efficient enough for 64-bit integers because per x would be too slow if range is huge.
So we need a global formula.

Key structural simplification:
For any valid pair with y > x, necessarily x and (y-x) are disjoint in bits and y < 2x.
Equivalently x is a submask of y, and the highest bit of y equals highest bit of x.
Thus for each y, valid x are exactly submasks of y that contain the highest bit of y.
Let hb = highest power of two <= y. Then x must be:
x = hb | t, where t is any submask of (y - hb).
And x <= y automatically.

Condition x >= L. Therefore for fixed y, number of valid x is:
# { t submask of low : hb | t >= L }
plus always included x=y from t=low, already counted.

So total answer:
sum_{y=L..R} count_submasks_ge_L(y)

Let low = y ^ hb. All candidate x are hb | t for t subset of low.
This is exactly the number of submasks of low that are >= (L - hb), if hb < L; otherwise all submasks.

We can compute:
For each block of y sharing same highest bit hb = 2^k, y = hb + low, 0 <= low < hb.
For low in some interval, sum over low of number of submasks t of low satisfying t >= T, where T=max(0, L-hb).

Using identity:
number of submasks of low = 2^{popcount(low)}.

And number of submasks t of low with t < T can be counted by bit DP.
Given constraints are not stated, but likely up to 1e18. We need O(log^2 R).

We compute F(N, L): number of valid pairs with L <= x <= y <= N.
Then answer for [L,R] is F(R,L), since lower bound applies only to x and y both >= L, and y is summed from L..R automatically because x<=y and x>=L.
So just sum y in [L,R].

Define for a fixed hb block [hb, upper]:
if hb >= L, all submasks allowed, contribution over low in [a..b]:
sum 2^{popcount(low)}
This over prefix has closed form:
S(m) = sum_{low=0..m} 2^{popcount(low)} via digit DP.

If hb < L, let T = L - hb (>0). Need:
count(low) = #submasks(low) - #submasks(low) with value < T
= 2^{pc(low)} - G(low,T)

Summed over low range. G-prefix can also be digit-DP over bits:
sum_{low<=m} # { t subset low, t < T }.
Swap counting:
for each t < T, count lows<=m with (low & t) = t.
This can be computed by digit DP per t, but too much.

Better direct joint DP on bits of low and t:
Count pairs (low,t) such that low<=m, t<T, and t subset low.
This is a standard 2-tight DP over bits, O(bits).

So we can compute H(m,T)=sum_{low=0..m} #submasks t of low with t<T.

Then contribution over prefix low<=m is:
P(m,hb,L)= S(m) if hb>=L else S(m)-H(m,L-hb)

Answer is sum over hb blocks intersecting [L,R].

*/

static long long pow2[65];

long long S_prefix_upto(unsigned long long m) {
    // sum_{x=0..m} 2^{popcount(x)}
    long long ans = 0;
    int ones = 0;
    for (int b = 63; b >= 0; --b) {
        if ((m >> b) & 1ULL) {
            ans = (ans + pow2[ones] * pow2[2 * b >= 64 ? 0 : 0]) % MOD; // placeholder avoided below
            // Need 3^b * 2^ones
            long long p3 = 1;
            // compute 3^b mod MOD on the fly is expensive; precompute instead
        }
    }
    return ans;
}

static long long pow3[65];

long long sum2pop_prefix(unsigned long long m) {
    // sum_{x=0..m} 2^{popcount(x)}
    long long ans = 0;
    int ones = 0;
    for (int b = 63; b >= 0; --b) {
        if ((m >> b) & 1ULL) {
            ans = (ans + pow2[ones] * pow3[b]) % MOD;
            ones++;
        }
    }
    ans = (ans + pow2[ones]) % MOD;
    return ans;
}

long long H_prefix(unsigned long long m, unsigned long long T) {
    // sum_{low=0..m} #{ t : t < T and (t & ~low)==0 }
    // digit DP over bits of (low, t)
    // states dp[lessM][lessT]
    long long dp[2][2] = {{1,0},{0,0}};
    for (int b = 63; b >= 0; --b) {
        long long ndp[2][2] = {{0,0},{0,0}};
        int mb = (m >> b) & 1ULL;
        int tb = (T >> b) & 1ULL;
        for (int lm = 0; lm < 2; ++lm) {
            for (int lt = 0; lt < 2; ++lt) {
                long long cur = dp[lm][lt];
                if (!cur) continue;
                for (int lowb = 0; lowb <= 1; ++lowb) {
                    if (!lm && lowb > mb) continue;
                    int nlm = lm || (lowb < mb);
                    for (int bit = 0; bit <= 1; ++bit) { // t bit
                        if (bit && !lowb) continue;      // subset condition
                        if (!lt) {
                            if (bit > tb) continue;
                        }
                        int nlt = lt || (bit < tb);
                        ndp[nlm][nlt] += cur;
                        if (ndp[nlm][nlt] >= MOD) ndp[nlm][nlt] -= MOD;
                    }
                }
            }
        }
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 2; ++j)
                dp[i][j] = ndp[i][j];
    }
    // Need t < T, so lessT must be 1. low <= m always included by both lessM states.
    return (dp[0][1] + dp[1][1]) % MOD;
}

long long block_prefix(unsigned long long m, unsigned long long hb, unsigned long long L) {
    // low in [0..m] for y = hb + low
    long long all = sum2pop_prefix(m);
    if (hb >= L) return all;
    unsigned long long T = L - hb;
    long long bad = H_prefix(m, T);
    long long res = all - bad;
    if (res < 0) res += MOD;
    return res;
}

int main() {
    unsigned long long L, R;
    if (scanf("%llu %llu", &L, &R) != 2) return 0;

    pow2[0] = 1;
    pow3[0] = 1;
    for (int i = 1; i <= 64; ++i) {
        pow2[i] = (pow2[i - 1] * 2) % MOD;
        pow3[i] = (pow3[i - 1] * 3) % MOD;
    }

    long long ans = 0;
    for (int k = 0; k < 63; ++k) {
        unsigned long long hb = 1ULL << k;
        unsigned long long start = hb;
        unsigned long long end = (hb << 1) - 1;
        if (end < L || start > R) continue;
        unsigned long long ys = (L > start ? L : start);
        unsigned long long ye = (R < end ? R : end);
        unsigned long long lowL = ys - hb;
        unsigned long long lowR = ye - hb;

        long long part = block_prefix(lowR, hb, L);
        if (lowL > 0) {
            part -= block_prefix(lowL - 1, hb, L);
            if (part < 0) part += MOD;
        }
        ans += part;
        if (ans >= MOD) ans -= MOD;
    }

    // handle highest bit 63 if needed? Inputs likely fit signed 64-bit positive, so not necessary.
    printf("%lld\n", ans % MOD);
    return 0;
}

