const int MOD = 1e9 + 7;
long long L, R;
// digit DP on bits from high to low
// state: bit pos, tightLx, tightRx, tightLy, tightRy, x_less_y (0: equal so far, 1: x < y confirmed)
map<tuple<int,int,int,int,int,int>, long long> memo;

long long dp(int pos, bool tlx, bool trx, bool tly, bool trY, bool xLessY) {
    if (pos < 0) return xLessY ? 1 : 1; // x <= y always since xLessY or equal
    // actually when pos<0, x==y if !xLessY, which is fine since x<=y
    auto key = make_tuple(pos,(int)tlx,(int)trx,(int)tly,(int)trY,(int)xLessY);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    int lx_bit = (L >> pos) & 1, rx_bit = (R >> pos) & 1;
    int ly_bit = (L >> pos) & 1, ry_bit = (R >> pos) & 1;

    long long res = 0;
    for (int bx = 0; bx <= 1; bx++) {
        if (tlx && bx < lx_bit) continue;
        if (trx && bx > rx_bit) continue;
        for (int by = bx; by <= 1; by++) { // by >= bx to maintain x&y=x... no, need (bx&by)==bx
            // x&y=x means if bx=1 then by=1
            if (bx == 1 && by == 0) continue;
            if (tly && by < ly_bit) continue;
            if (trY && by > ry_bit) continue;
            bool ntlx = tlx && (bx == lx_bit);
            bool ntrx = trx && (bx == rx_bit);
            bool ntly = tly && (by == ly_bit);
            bool ntrY = trY && (by == ry_bit);
            bool nxLessY = xLessY || (bx < by);
            // ensure x <= y: if bx > by, invalid (but we already have by >= bx when bx=1)
            // actually bx=0,by=0 or bx=0,by=1 or bx=1,by=1
            if (bx > by) continue;
            res = (res + dp(pos-1, ntlx, ntrx, ntly, ntrY, nxLessY)) % MOD;
        }
    }
    return memo[key] = res;
}

