using namespace std;
using int64 = long long;
const int MOD = 1e9 + 7;

int64 sum_lowbit(int64 n) {
    int64 res = 0;
    int64 pow2 = 1;
    while (pow2 <= n) {
        int64 full_cycles = n / (pow2 * 2);
        int64 remainder = n % (pow2 * 2);
        res += full_cycles * pow2;
        if (remainder >= pow2)
            res += remainder - pow2 + 1;
        pow2 <<= 1;
    }
    return res;
}

