// Sum of floor(n / i) for i = 1..n in O(sqrt n)
long long floor_sum_upto(long long n) {
    long long res = 0;
    for (long long l = 1; l <= n; ) {
        long long q = n / l;
        long long r = n / q;
        res += q * (r - l + 1);
        l = r + 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long L, R;
    cin >> L >> R;

    // Key observation:
    // Let y = qx + r, 0 <= r < x.
    // Condition: y % x = y XOR x  =>  r = y XOR x.
    //
    // Since y XOR x = r < x, all bits of y and x above the highest bit of x-1
    // must cancel, which forces q = 1 and x & r = 0.
    // Thus y = x + r with 0 <= r < x and x & r = 0.
    //
    // For fixed y, valid x are exactly the non-zero submasks of y:
    // x & (y-x) = 0  <=> no carry in x + (y-x) = y
    // <=> x is a submask of y.
    //
    // Therefore number of valid x for fixed y equals (# non-zero submasks of y)
    // = 2^{popcount(y)} - 1.
    //
    // But x must also satisfy x >= L, not just x >= 1.
    // A more useful equivalent characterization:
    // For each x, valid y are y = x | t where t is any submask of (~x) within bits below msb(x),
    // i.e. count = 2^{number of 0-bits below highest set bit of x)}.
    // This equals 2^{floor(log2 x) - popcount(lower bits of x)}.
    //
    // A cleaner closed form:
    // Let k = floor(log2 x). Then among k lower bits, if x has c ones there,
    // number of allowed t is 2^(k-c).
    // Since popcount(x) = c+1, this is 2^(k+1-popcount(x)).
    //
    // Summing directly is hard for large range, but there is a classic identity:
    // f(x) = largest power of 2 dividing x? No.
    // In fact this count equals 2^k / lowbit_oddpart? Still not convenient.
    //
    // Another equivalent and very useful form:
    // For each x, count of valid y equals floor((2^{k+1}-1)/x)? No.
    //
    // Instead, we use the original condition to derive:
    // y%x = y^x implies y = x + r, r<x, x&r=0.
    // For fixed x, every such y lies in [x, 2x-1].
    // Hence with upper bound R, count for x is number of r in [0, min(x-1, R-x)] with x&r=0.
    // This is awkward for arbitrary [L,R].
    //
    // There is a stronger simplification:
    // For any valid pair, y < 2x, so x > y/2.
    // For fixed y, x in (y/2, y], and x being a submask of y.
    // Any submask of y larger than y/2 must include the highest bit of y, and then
    // can choose any subset of lower set bits. Thus number of such x is exactly 2^(popcount(y)-1).
    // Since x=y is included, all these satisfy x<=y.
    //
    // So without lower bound on x, total over y is sum 2^(popcount(y)-1).
    // With x>=L, for fixed y we need submasks x>y/2 and x>=L.
    // Let highest bit of y be 2^k, and lower set-bit mask be s.
    // Such x are 2^k + t where t is any submask of s.
    // Need x >= max(L, 2^k).
    //
    // Counting submasks >= threshold is complicated.
    //
    // We switch to counting by x and use a digit-DP style formula over interval [L,R].
    // For fixed x, all valid y are x + r where r is a submask of zero-bits among lower k bits of x,
    // where k=floor(log2 x). So y values are exactly x OR t over t submask of ((1<<k)-1) ^ (x lower part).
    // Thus number of valid y <= R equals number of such t with t <= R-x.
    //
    // This can be counted bitwise. Since constraints are not provided, we implement
    // a binary trie-like DP per x would be too slow for huge ranges.
    //
    // We need a simpler formula. Observe valid y for x form all numbers in [x,2^{k+1}-1]
    // that have all 1-bits of x. Therefore count for x up to upper bound U is:
    // if U < x => 0
    // else count of supermasks of x within [x, min(U,2^{k+1}-1)].
    // Since only lower k bits vary, this is exactly number of submasks t of zero positions
    // such that t <= M where M = min(U,2^{k+1}-1)-x.
    //
    // Still thresholded submask count.
    //
    // Given typical constraints of such problems are up to 1e6 or 1e7? Not stated.
    // We provide an O((R-L+1) * 64) solution, which is safe for moderate ranges.
    // For each x, count via digit DP on lower bits.

    auto count_for_x = [&](long long x, long long U) -> long long {
        if (U < x) return 0;
        int k = 63 - __builtin_clzll((unsigned long long)x);
        long long upper = min(U, (1LL << (k + 1)) - 1);
        long long M = upper - x; // need t <= M
        // allowed bits for t are zero-bits of x among positions [0..k-1]
        long long allowed = ((1LL << k) - 1) ^ (x & ((1LL << k) - 1));

        long long dp_equal = 1, dp_less = 0;
        for (int b = k - 1; b >= 0; --b) {
            long long ndp_equal = 0, ndp_less = 0;
            int mb = (M >> b) & 1;
            bool can1 = (allowed >> b) & 1;

            // from less: any allowed choice
            long long choices = 1 + (can1 ? 1 : 0);
            ndp_less = (ndp_less + dp_less * choices) % MOD;

            // from equal
            // choose tb = 0
            if (0 < mb) ndp_less = (ndp_less + dp_equal) % MOD;
            else if (0 == mb) ndp_equal = (ndp_equal + dp_equal) % MOD;

            // choose tb = 1 if allowed
            if (can1) {
                if (1 < mb) ndp_less = (ndp_less + dp_equal) % MOD;
                else if (1 == mb) ndp_equal = (ndp_equal + dp_equal) % MOD;
                // if 1 > mb impossible
            }

            dp_equal = ndp_equal;
            dp_less = ndp_less;
        }
        return (dp_equal + dp_less) % MOD;
    };

    long long ans = 0;
    for (long long x = L; x <= R; ++x) {
        ans += count_for_x(x, R);
        if (ans >= MOD) ans -= MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long L = sc.nextLong();
        long R = sc.nextLong();
        sc.close();

        long ans = 0;

        for (long x = 1; x <= R; x++) {
            // We need y such that x <= y <= R and y % x == y ^ x.
            // Condition holds iff y ^ x < x.
            // For given x, the smallest y that satisfies y ^ x < x is:
            // find highest bit where x has 1, set it to 0 in y, lower bits can be anything.
            // So y = (x with that bit cleared) + any bits below it.

            long bit = Long.highestOneBit(x);
            long base = x ^ bit; // clear that bit
            // Now y = base + t, where t ranges from 0 to bit-1
            long low = base;
            long high = base + bit - 1;

            if (high < x) continue; // no y >= x
            if (low < x) low = x;
            if (low > R) continue;
            if (high > R) high = R;

            ans = (ans + (high - low + 1) % MOD) % MOD;
        }

        System.out.println(ans);
    }
}

