import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long L = fs.nextLong();
        long R = fs.nextLong();

        long ans = 0;

        // For x > y/2 and x <= y, we have y % x = y - x.
        // Then condition becomes:
        //   y - x = y ^ x
        // Let a = y - x >= 0, so y = x + a.
        // Then:
        //   (x + a) ^ x = a
        // This holds iff x and a have no common set bit, i.e. (x & a) = 0.
        //
        // Since y = x + a and x <= y <= R, also x >= L.
        // For fixed a, valid x satisfy:
        //   L <= x <= R - a
        //   x >= a+1   (because x > y/2 <=> x > a)
        //   (x & a) = 0
        //
        // Therefore count for each a in [0, R-L]:
        //   x in [max(L, a+1), R-a] with (x & a)=0
        //
        // Special case a = 0 gives x = y, always valid: count = R-L+1.
        //
        // We count numbers in [0..N] with (x & a)=0 using digit DP on bits.

        long maxA = R - L;
        for (long a = 0; a <= maxA; a++) {
            long lo = Math.max(L, a + 1);
            long hi = R - a;
            if (a == 0) lo = L; // x=y allowed
            if (lo > hi) continue;

            long cnt = countNoCommonBits(hi, a) - countNoCommonBits(lo - 1, a);
            cnt %= MOD;
            if (cnt < 0) cnt += MOD;
            ans += cnt;
            if (ans >= MOD) ans -= MOD;
        }

        System.out.println(ans % MOD);
    }

    // Counts x in [0..n] such that (x & a) == 0
    static long countNoCommonBits(long n, long a) {
        if (n < 0) return 0;
        long res = 1; // product over free bits under upper bound handled by digit DP
        long dpEqual = 1;
        long dpLess = 0;

        for (int b = 62; b >= 0; b--) {
            int nb = ((n >> b) & 1L) != 0 ? 1 : 0;
            int ab = ((a >> b) & 1L) != 0 ? 1 : 0;

            long newEqual = 0, newLess = 0;

            // from equal state
            if (dpEqual != 0) {
                if (ab == 1) {
                    // x bit must be 0
                    if (0 == nb) newEqual = (newEqual + dpEqual) % MOD;
                    else newLess = (newLess + dpEqual) % MOD;
                } else {
                    // x bit can be 0 or 1
                    if (nb == 0) {
                        newEqual = (newEqual + dpEqual) % MOD; // choose 0
                    } else {
                        newLess = (newLess + dpEqual) % MOD;   // choose 0 < 1
                        newEqual = (newEqual + dpEqual) % MOD; // choose 1 = 1
                    }
                }
            }

            // from less state
            if (dpLess != 0) {
                if (ab == 1) {
                    newLess = (newLess + dpLess) % MOD; // must choose 0
                } else {
                    newLess = (newLess + dpLess * 2) % MOD; // choose 0 or 1
                }
            }

            dpEqual = newEqual;
            dpLess = newLess;
        }

        return (dpEqual + dpLess) % MOD;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
